sql.if:
and exists (
select 1 from t_rule_hit h
where h.alert_id = a.id

    and h.session_id = #{criteria.sessionId}


    and h.node_id = #{criteria.nodeId}


    and h.device_code = #{criteria.deviceCode}

)

mapper.select:
select *
from t_alert_event
where tenant_id = #{tenantId}
  and id = #{id}
limit 1

select *
from t_alert_event
where tenant_id = #{tenantId}
  and id = #{id}
limit 1 for update

mapper.update:
update t_alert_event
set status = 1,
    handle_user_id = #{handleUserId},
    handle_time = #{handleTime},
    version = version + 1
where tenant_id = #{tenantId}
  and id = #{id}
  and status = 0
  and version = #{expectedVersion}

mapper.select:
select a.level as code, count(*) as count from t_alert_event a
a.tenant_id = #{tenantId}
group by a.level order by a.level

select a.status as code, count(*) as count from t_alert_event a
a.tenant_id = #{tenantId}
group by a.status order by a.status
